function writeSheetData(ss, name, headers, rows) {
  let s = ss.getSheetByName(name);
  if (s) {
    s.clear();
  } else {
    s = ss.insertSheet(name);
  }
  const all = [headers, ...rows];
  // Write in chunks to prevent timeout
  const chunkSize = 500;
  for (let i = 0; i < all.length; i += chunkSize) {
    const chunk = all.slice(i, i + chunkSize);
    s.getRange(i + 1, 1, chunk.length, headers.length).setValues(chunk);
  }
  s.getRange(1, 1, 1, headers.length).setFontWeight('bold').setBackground('#f1f5f9');
}
